'use client';

import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';
import { useRef } from 'react';
import { Project } from '@/lib/data';
import { useLanguage } from './LanguageProvider';

export default function ProjectCard({ project }: { project: Project }) {
  const { t, locale } = useLanguage();
  const ref = useRef<HTMLDivElement>(null);

  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const rotateX = useSpring(useTransform(y, [-0.5, 0.5], [8, -8]), {
    stiffness: 200,
    damping: 20,
  });
  const rotateY = useSpring(useTransform(x, [-0.5, 0.5], [-8, 8]), {
    stiffness: 200,
    damping: 20,
  });

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const cx = (e.clientX - rect.left) / rect.width - 0.5;
    const cy = (e.clientY - rect.top) / rect.height - 0.5;
    x.set(cx);
    y.set(cy);
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.div
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ rotateX, rotateY, transformStyle: 'preserve-3d', perspective: 800 }}
      className="glass-card rounded-2xl p-6 group flex flex-col h-full cursor-pointer"
      whileHover={{ scale: 1.02 }}
      transition={{ duration: 0.2 }}
    >
      <div style={{ transform: 'translateZ(20px)' }}>
        {project.imageUrl && (
          <div className="w-full h-48 mb-4 rounded-xl overflow-hidden">
            <img
              src={project.imageUrl}
              alt={project.title[locale]}
              className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
            />
          </div>
        )}

        <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2 group-hover:text-blue-500 dark:group-hover:text-blue-400 transition-colors">
          {project.title[locale]}
        </h3>
        <p className="text-gray-500 dark:text-gray-400 mb-4 line-clamp-3 flex-grow text-sm leading-relaxed">
          {project.description[locale]}
        </p>

        <div className="flex flex-wrap gap-2 mb-6">
          {project.techStack.split(',').map((tech) => (
            <span
              key={tech}
              className="px-3 py-1 text-xs font-medium rounded-full bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20"
            >
              {tech.trim()}
            </span>
          ))}
        </div>

        <div className="flex gap-4 items-center mt-auto">
          {project.githubUrl && (
            <a
              href={project.githubUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="text-sm text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors flex items-center gap-2"
            >
              {t.portfolio.gitlab}
            </a>
          )}
          {project.demoUrl && (
            <a
              href={project.demoUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="text-sm text-blue-500 dark:text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-2"
            >
              {t.portfolio.liveDemo}
            </a>
          )}
        </div>
      </div>
    </motion.div>
  );
}
