'use client';

import { motion } from 'framer-motion';

const ORBS = [
  {
    size: 'w-[500px] h-[500px]',
    color: 'from-blue-500/20 to-cyan-400/10',
    position: 'top-[-15%] left-[-10%]',
    duration: 20,
    delay: 0,
  },
  {
    size: 'w-[400px] h-[400px]',
    color: 'from-violet-500/15 to-purple-500/10',
    position: 'top-[40%] right-[-8%]',
    duration: 25,
    delay: 3,
  },
  {
    size: 'w-[350px] h-[350px]',
    color: 'from-cyan-400/12 to-blue-500/15',
    position: 'bottom-[10%] left-[20%]',
    duration: 22,
    delay: 6,
  },
  {
    size: 'w-[300px] h-[300px]',
    color: 'from-indigo-500/10 to-blue-400/12',
    position: 'top-[60%] left-[60%]',
    duration: 18,
    delay: 1,
  },
];

export default function AnimatedBackground() {
  return (
    <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
      {ORBS.map((orb, index) => (
        <motion.div
          key={index}
          className={`absolute ${orb.size} ${orb.position} rounded-full bg-gradient-to-br ${orb.color} blur-3xl`}
          animate={{
            x: [0, 30, -20, 15, 0],
            y: [0, -25, 15, -30, 0],
            scale: [1, 1.1, 0.95, 1.05, 1],
            opacity: [0.6, 0.8, 0.5, 0.7, 0.6],
          }}
          transition={{
            duration: orb.duration,
            delay: orb.delay,
            repeat: Infinity,
            ease: 'easeInOut',
          }}
        />
      ))}

      {/* Subtle grid lines overlay */}
      <div
        className="absolute inset-0 opacity-[0.03] dark:opacity-[0.04]"
        style={{
          backgroundImage:
            'linear-gradient(rgba(255,255,255,0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.1) 1px, transparent 1px)',
          backgroundSize: '80px 80px',
        }}
      />

      {/* Animated diagonal lines */}
      <motion.div
        className="absolute inset-0 opacity-[0.015] dark:opacity-[0.02]"
        style={{
          backgroundImage:
            'linear-gradient(45deg, rgba(59,130,246,0.3) 1px, transparent 1px)',
          backgroundSize: '60px 60px',
        }}
        animate={{
          backgroundPosition: ['0px 0px', '60px 60px'],
        }}
        transition={{
          duration: 15,
          repeat: Infinity,
          ease: 'linear',
        }}
      />
    </div>
  );
}
