'use client';

import { motion, useScroll, useTransform } from 'framer-motion';
import { useRef } from 'react';

interface BookPageProps {
  children: React.ReactNode;
  index: number;
  className?: string;
}

export default function BookPage({ children, index, className = '' }: BookPageProps) {
  const ref = useRef<HTMLDivElement>(null);

  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ['start end', 'start center'],
  });

  // 3D flip like opening a book page
  const rotateX = useTransform(scrollYProgress, [0, 1], [22, 0]);
  const y = useTransform(scrollYProgress, [0, 1], [140, 0]);
  const opacity = useTransform(scrollYProgress, [0, 0.5], [0.3, 1]);
  const scale = useTransform(scrollYProgress, [0, 1], [0.92, 1]);
  const shadowOpacity = useTransform(scrollYProgress, [0, 1], [0.5, 0]);

  return (
    <div
      ref={ref}
      className={`relative ${className}`}
      style={{
        zIndex: index,
        perspective: 1400,
        transformStyle: 'preserve-3d',
      }}
    >
      <motion.div
        style={{
          rotateX,
          y,
          opacity,
          scale,
          transformOrigin: 'top center',
          transformStyle: 'preserve-3d',
        }}
        className="relative"
      >
        {children}
      </motion.div>

      {/* Page fold / crease line at bottom */}
      <div className="absolute bottom-0 left-0 right-0 h-[2px] bg-gradient-to-r from-transparent via-gray-400/20 to-transparent pointer-events-none" />

      {/* Page edge shadow — creates the feeling of pages beneath */}
      <motion.div
        className="absolute -bottom-8 left-6 right-6 h-8 rounded-[50%] blur-2xl pointer-events-none"
        style={{
          opacity: shadowOpacity,
          background:
            index % 2 === 0
              ? 'rgba(59, 130, 246, 0.3)'
              : 'rgba(139, 92, 246, 0.3)',
        }}
      />

      {/* Paper thickness / page curl visual */}
      <div
        className="absolute -bottom-[1px] left-0 right-0 h-4 pointer-events-none"
        style={{
          background: 'linear-gradient(to bottom, rgba(255,255,255,0.04), transparent)',
        }}
      />
    </div>
  );
}
